use blit_core::fs_enum::FileFilter;
use blit_core::transfers::filter::resolve_excludes;
use std::path::Path;
fn main() {
    let pres = ["", ".", "./.", "*", "**", "***", "a", "a/**", "a/*", r"\*", r"\**", "[*]*", "{a,**", "{**", "{,**", "./**", "**/**", "?", "a.", r"\."];
    let posts = ["", "/", "x", "*", "**", "**/x", "**x", "*/x", "x/", "x\\/", "x}", "x,b}", "x,}", "x,**/a}", "./x", "[a]", "\\/x"];
    let names = ["a", "x", "cache", "a/x", "b/x", "a/b/x", "a/b", "*/x", "./x", "a/./x", ".a/x", "a./x", "a/b/c/x", "a/*/x", "abcx", "b", "[a]", "*/b/x"];
    let mut diffs=0; let mut checked=0;
    for pre in pres { for post in posts {
        let p=format!(r"{}\/{}",pre,post);
        if globset::Glob::new(&p).is_err() { continue }
        let resolved=resolve_excludes(&[p.clone()],None);
        let q=&resolved.patterns[0];
        let mut before=FileFilter::default(); before.exclude_files=vec![p.clone()];
        let mut after=FileFilter::default(); after.exclude_files=vec![q.clone()];
        for name in names {
            let path=Path::new(name);
            let b=before.allows_entry(Some(path),path,1,None);
            let a=after.allows_entry(Some(path),path,1,None);
            checked+=1;
            if a!=b { diffs+=1; println!("{:?} -> {:?} on {:?}: before={}, after={}",p,q,name,b,a); }
        }
    }}
    println!("checked={checked} differences={diffs}");
}
